def compare_versions(a: str, b: str) -> int:
    """Compare two semantic version strings.

    Returns:
        -1 if a < b
         0 if a == b
         1 if a > b
    """
    def split_version(v: str):
        # Separate build metadata
        main_and_meta = v.split('+', 1)[0]
        # Separate pre-release
        core, sep, pre = main_and_meta.partition('-')
        major, minor, patch = map(int, core.split('.'))
        pre_ids = pre.split('.') if sep else []
        return major, minor, patch, pre_ids

    def compare_identifiers(a_ids, b_ids):
        # Compare pre-release identifiers
        for ai, bi in zip(a_ids, b_ids):
            ai_num = ai.isdigit()
            bi_num = bi.isdigit()
            if ai_num and bi_num:
                # numeric comparison
                a_val, b_val = int(ai), int(bi)
                if a_val < b_val:
                    return -1
                if a_val > b_val:
                    return 1
            elif ai_num and not bi_num:
                return -1  # numeric < non-numeric
            elif not ai_num and bi_num:
                return 1   # non-numeric > numeric
            else:
                # ASCII comparison
                if ai < bi:
                    return -1
                if ai > bi:
                    return 1
        # All matched so far; longer list is greater
        if len(a_ids) < len(b_ids):
            return -1
        if len(a_ids) > len(b_ids):
            return 1
        return 0

    a_major, a_minor, a_patch, a_pre = split_version(a)
    b_major, b_minor, b_patch, b_pre = split_version(b)

    # Compare core versions
    if a_major != b_major:
        return -1 if a_major < b_major else 1
    if a_minor != b_minor:
        return -1 if a_minor < b_minor else 1
    if a_patch != b_patch:
        return -1 if a_patch < b_patch else 1

    # Core equal; handle pre-release presence
    if not a_pre and not b_pre:
        return 0
    if not a_pre:
        return 1  # a has no pre-release, higher
    if not b_pre:
        return -1  # b has no pre-release, higher

    # Both have pre-release; compare identifiers
    return compare_identifiers(a_pre, b_pre)
